create table if not exists public.workouts(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,date date not null,type text not null,distance numeric default 0,duration numeric default 0,hr integer,effort integer,surface text,notes text,updated_at timestamptz default now());alter table public.workouts enable row level security;create policy "Read own workouts" on public.workouts for select using(auth.uid()=user_id);create policy "Insert own workouts" on public.workouts for insert with check(auth.uid()=user_id);create policy "Update own workouts" on public.workouts for update using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "Delete own workouts" on public.workouts for delete using(auth.uid()=user_id);create index if not exists workouts_user_date_idx on public.workouts(user_id,date desc);